import 'dart:ui';import 'package:flutter/material.dart';import 'package:introduction_screen/introduction_screen.dart';import '../../generated/l10n.dart';import 'app_colors.dart';import '../../Config/Assets/image_png.dart';import '../../Features/Boarding/presentation/widgets/build_page_view_model.dart';class AppList {  static List<PageViewModel> buildPagesIntroductionScreen(      S local) {    return [      buildPageViewModel(        title: local.boarding1_title,        body: local.boarding1_body,        image: AppImagesPng.boarding1,      ),      buildPageViewModel(        title: local.boarding2_title,        body: local.boarding2_body,        image: AppImagesPng.boarding2,      ),      buildPageViewModel(        title: local.boarding3_title,        body: local.boarding3_body,        image: AppImagesPng.boarding3,      ),    ];  }  static List<Widget> gradientColorsBackground = [    Container(      decoration: BoxDecoration(        gradient: LinearGradient(          begin: Alignment.centerLeft,          end: Alignment.centerRight,          colors: AppColors.gradientColors,          tileMode: TileMode.repeated,        ),      ),    ),    Positioned.fill(      child: BackdropFilter(        filter: ImageFilter.blur(sigmaX: 10, sigmaY: 10),        blendMode: BlendMode.darken,        child: Container(          color: Colors.black.withAlpha(0x40),        ),      ),    ),  ];}